import{_ as o,o as t,c as a,a0 as i}from"./chunks/framework.DqMqoJl9.js";const p=JSON.parse('{"title":"从 SQLite 迁移踩坑到多账号并行：抖音监控工具工程化复盘","description":"","frontmatter":{"title":"从 SQLite 迁移踩坑到多账号并行：抖音监控工具工程化复盘","date":"2026-09-29T00:00:00.000Z","tags":["Python","SQLite","爬虫","工程实践"]},"headers":[],"relativePath":"posts/douyin-tool-engineering.md","filePath":"posts/douyin-tool-engineering.md","lastUpdated":null}'),r={name:"posts/douyin-tool-engineering.md"};function n(d,e,l,c,s,_){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="从-sqlite-迁移踩坑到多账号并行-抖音监控工具工程化复盘" tabindex="-1">从 SQLite 迁移踩坑到多账号并行：抖音监控工具工程化复盘 <a class="header-anchor" href="#从-sqlite-迁移踩坑到多账号并行-抖音监控工具工程化复盘" aria-label="Permalink to &quot;从 SQLite 迁移踩坑到多账号并行：抖音监控工具工程化复盘&quot;">​</a></h1><p>抖音数据监控工具原来用 JSON 文件存扫描历史，单账号串行扫描。这轮工程化做了四件事，踩了三个坑。</p><h2 id="_1-sqlite-迁移-两个隐蔽的坑" tabindex="-1">1. SQLite 迁移：两个隐蔽的坑 <a class="header-anchor" href="#_1-sqlite-迁移-两个隐蔽的坑" aria-label="Permalink to &quot;1. SQLite 迁移：两个隐蔽的坑&quot;">​</a></h2><p><strong>坑一：非重入锁死锁。</strong> <code>_get_conn()</code> 与外层 <code>_conn_lock</code> 嵌套，RLock 变成不可重入，首次并发写直接死锁。解法：拆成 <code>_init_lock</code>（仅初始化）+ <code>_conn_lock</code>（每次读写事务串行）双锁。</p><p><strong>坑二：主键用毫秒时间戳导致数据互相覆盖。</strong> <code>INSERT OR REPLACE</code> 用 <code>int(time.time()*1000)</code> 当主键，同一毫秒内多条告警互相覆盖——单测测出 205 条只剩 11 条。解法：<code>SELECT MAX(id)</code> 单调递增主键。</p><p><strong>坑三：隐藏的重复函数定义。</strong> <code>get_video_trend</code> 定义了两次，后者覆盖前者，导致 <code>limit</code> 参数失效、趋势图字段恒为空。合并为单函数。</p><h2 id="_2-多账号并行扫描" tabindex="-1">2. 多账号并行扫描 <a class="header-anchor" href="#_2-多账号并行扫描" aria-label="Permalink to &quot;2. 多账号并行扫描&quot;">​</a></h2><p><code>ThreadPoolExecutor</code> 每账号独立 Crawler 实例，并发上限 3 防风控，进度更新加锁，账号级失败保留浏览器重启重试。</p><h2 id="_3-飞书表格-upsert" tabindex="-1">3. 飞书表格 upsert <a class="header-anchor" href="#_3-飞书表格-upsert" aria-label="Permalink to &quot;3. 飞书表格 upsert&quot;">​</a></h2><p>懒加载全表建 <code>video_id → 行号</code> 映射：已存在更新原行、新视频追加。用 <code>^\\d{6,}$</code> 过滤脏数据——真实表格里混着「3.7万」「2193」这类错位历史数据，只让纯数字 ID 参与 upsert。</p><h2 id="_4-可观测性与交付" tabindex="-1">4. 可观测性与交付 <a class="header-anchor" href="#_4-可观测性与交付" aria-label="Permalink to &quot;4. 可观测性与交付&quot;">​</a></h2><ul><li>启动自检：依赖 / cookies / 飞书配置 / webhook / 数据目录 / SQLite 全链路检查</li><li>Docker + GitHub Actions CI，38 项单测</li></ul><h2 id="收获" tabindex="-1">收获 <a class="header-anchor" href="#收获" aria-label="Permalink to &quot;收获&quot;">​</a></h2><p>数据库设计时主键策略要想清楚；并发改造前先跑单测建立行为基线；真实业务数据里到处都是脏数据，防御性过滤是刚需。</p><blockquote><p>完整代码见 <a href="https://github.com/lszlovelhl/douyin_tool" target="_blank" rel="noreferrer">douyin_tool</a></p></blockquote>',15)])])}const u=o(r,[["render",n]]);export{p as __pageData,u as default};
